scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode) {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsCodeQuality(ast).debugStatements();
    var report = new global.EcsReport(engine, {
        ruleId: 'JS-001',
        title: 'Debug statements left in code',
        recommendation: 'Remove debug output before promotion. For diagnostics that should stay, use gs.debug() / gs.info() with a clear source, guarded by a system property where needed.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
